//! The interpreter of `test-vectors/direct_range.json` (LD-0105): one runner for every section,
//! asserting each row and counting them, so a skipped section is a failure, never a pass.
//! The file is generated by `test-vectors/tools/make_direct_range_vectors.py` (an independent
//! implementation of the spec text) and guarded by `check-direct-range-vectors-generated.sh`.

use serde_json::Value;

use super::{
    PieceCutter, RangeBudget, RangeConfig, RangePlanner, RangePoll, demand_chunks, range_window, storage_in_flight,
};
use crate::direct_transfer::window::Geometry;
use crate::direct_transfer::wire::{
    CAP_OBJECT_DOWNLOAD_V1, CHUNK_OVERHEAD, ChunkGrant, Discovery, DownloadGrantRequest, DownloadGrantResponse,
    StorageBucket,
};

pub const RANGE_VECTORS_JSON: &str = include_str!("../../../../test-vectors/direct_range.json");

const T0: i64 = 1_800_000_000_000;
const FILE: &str = "11111111-1111-4111-8111-111111111111";
const VERSION: &str = "22222222-2222-4222-8222-222222222222";

/// Rows run per section.
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub struct RangeReport {
    pub slots: usize,
    pub window: usize,
    pub demand_chunks: usize,
    pub pieces: usize,
    pub budget_steps: usize,
    pub planner_steps: usize,
}

fn rows<'a>(v: &'a Value, key: &str) -> &'a Vec<Value> {
    v[key].as_array().unwrap_or_else(|| panic!("section {key}"))
}

fn u(v: &Value) -> u64 {
    v.as_u64().unwrap_or_else(|| panic!("a number, got {v}"))
}

/// What the file says should run.
pub fn expected_report() -> RangeReport {
    let v: Value = serde_json::from_str(RANGE_VECTORS_JSON).unwrap();
    let steps = |key: &str| rows(&v, key).iter().map(|s| rows(s, "steps").len()).sum();
    RangeReport {
        slots: rows(&v, "slots").len(),
        window: rows(&v, "window").len(),
        demand_chunks: rows(&v, "demand_chunks").len(),
        pieces: rows(&v, "pieces").len(),
        budget_steps: steps("budget"),
        planner_steps: steps("planner"),
    }
}

/// Run every row; panics on the first that disagrees.
pub fn run_all() -> RangeReport {
    let v: Value = serde_json::from_str(RANGE_VECTORS_JSON).unwrap();
    let mut r = RangeReport::default();
    for row in rows(&v, "slots") {
        let got = storage_in_flight(u(&row["share"]), u(&row["chunk_size"]));
        assert_eq!(u64::from(got), u(&row["expect"]), "slots: {}", row["name"]);
        r.slots += 1;
    }
    for row in rows(&v, "window") {
        let got = range_window(u(&row["server_max"]) as u32, u(&row["slots"]) as u32);
        assert_eq!(u64::from(got), u(&row["expect"]), "window: {}", row["name"]);
        r.window += 1;
    }
    for row in rows(&v, "demand_chunks") {
        let n = u(&row["chunk_count"]) as u32;
        let size = u(&row["original_size"]);
        let g = Geometry {
            chunk_count: n,
            chunk_size: u(&row["chunk_size"]),
            encrypted_size: size + CHUNK_OVERHEAD * u64::from(n),
            original_size: size,
        };
        let got = demand_chunks(&g, u(&row["offset"]), u(&row["len"]))
            .map(|(a, b)| serde_json::json!([a, b]))
            .unwrap_or(Value::Null);
        assert_eq!(got, row["expect"], "demand_chunks: {}", row["name"]);
        r.demand_chunks += 1;
    }
    for row in rows(&v, "pieces") {
        let size = u(&row["file_size"]);
        let stride = u(&row["chunk_size"]);
        let mut cutter = PieceCutter::new(size);
        let mut got = Vec::new();
        for c in rows(row, "order") {
            let lo = u(c) * stride;
            let hi = (lo + stride).min(size);
            let plain = vec![0u8; (hi - lo) as usize];
            let pieces = cutter.cut(lo, &plain).unwrap();
            got.push(serde_json::json!(
                pieces.iter().map(|p| [p.offset(), p.len()]).collect::<Vec<_>>()
            ));
        }
        assert_eq!(Value::Array(got), row["expect"], "pieces: {}", row["name"]);
        assert_eq!(
            cutter.held_bytes(),
            0,
            "pieces: {}: nothing is left behind",
            row["name"]
        );
        r.pieces += 1;
    }
    for scenario in rows(&v, "budget") {
        let mut b = RangeBudget::new(u(&scenario["budget"]));
        for step in rows(scenario, "steps") {
            let s = u(&step["session"]);
            let got = match step["op"].as_str().unwrap() {
                "lease" => Some(b.lease(s)),
                "hold" => Some(b.try_hold(s, u(&step["len"]))),
                "unhold" => {
                    b.unhold(s, u(&step["len"]));
                    None
                }
                "release" => {
                    b.release(s);
                    None
                }
                other => panic!("budget op {other}"),
            };
            if let Some(got) = got {
                assert_eq!(
                    Some(got),
                    step["expect"].as_bool(),
                    "budget: {}: {step}",
                    scenario["name"]
                );
            }
            assert_eq!(
                b.leased() as u64,
                u(&step["after"]["leased"]),
                "budget: {}: {step}",
                scenario["name"]
            );
            assert_eq!(
                b.total_held(),
                u(&step["after"]["total_held"]),
                "budget: {}: {step}",
                scenario["name"]
            );
            r.budget_steps += 1;
        }
    }
    for scenario in rows(&v, "planner") {
        r.planner_steps += run_planner(scenario);
    }
    r
}

fn discovery() -> Discovery {
    Discovery {
        download: vec![CAP_OBJECT_DOWNLOAD_V1.into()],
        storage_hosts: vec!["s3.storage.test".into()],
        storage_buckets: vec![StorageBucket {
            host: "s3.storage.test".into(),
            bucket: "bb-01".into(),
        }],
        max_window: Some(32),
        ..Default::default()
    }
}

fn grants_for(g: Geometry, request: &DownloadGrantRequest, now_ms: i64) -> DownloadGrantResponse {
    let end = (request.start_index + request.count).min(g.chunk_count);
    let expires = chrono::DateTime::from_timestamp_millis(now_ms + 300_000)
        .unwrap()
        .to_rfc3339_opts(chrono::SecondsFormat::Secs, true);
    DownloadGrantResponse {
        transport: CAP_OBJECT_DOWNLOAD_V1.into(),
        file_id: FILE.into(),
        object_version_id: VERSION.into(),
        chunk_count: g.chunk_count,
        chunk_size: g.chunk_size,
        encrypted_size: g.encrypted_size,
        original_size: g.original_size,
        grants: (request.start_index..end)
            .map(|i| ChunkGrant {
                index: i,
                method: "GET".into(),
                url: format!("https://s3.storage.test/bb-01/t/v/{i}.bin?X-Amz-Signature=SIG{i}"),
                length: g.chunk_length(i).unwrap(),
                expires_at: expires.clone(),
            })
            .collect(),
        next_index: (end < g.chunk_count).then_some(end),
    }
}

fn run_planner(scenario: &Value) -> usize {
    let name = scenario["name"].as_str().unwrap();
    let n = u(&scenario["chunk_count"]) as u32;
    let stride = u(&scenario["chunk_size"]);
    let original = stride * u64::from(n - 1) + 500;
    let g = Geometry {
        chunk_count: n,
        chunk_size: stride,
        encrypted_size: original + CHUNK_OVERHEAD * u64::from(n),
        original_size: original,
    };
    let cfg = RangeConfig::from_discovery(&discovery(), u(&scenario["share"]), 7);
    let mut p = RangePlanner::new(cfg, discovery(), "https://api.beebeeb.test", FILE, VERSION);
    let mut now = T0;
    let mut last: Option<DownloadGrantRequest> = None;
    let mut steps = 0;
    for step in rows(scenario, "steps") {
        match step["op"].as_str().unwrap() {
            "demand" => p.demand(u(&step["id"]), u(&step["offset"]), u(&step["len"])).unwrap(),
            "cancel" => p.cancel(u(&step["id"])),
            "advance" => now += u(&step["ms"]) as i64,
            "answer" => {
                let request = last
                    .take()
                    .unwrap_or_else(|| panic!("{name}: an answer with no window asked"));
                p.window_answered(grants_for(g, &request, now), now)
                    .unwrap_or_else(|e| panic!("{name}: {e}"));
            }
            "poll" => {
                let got = p.poll_with(now, !step["no_fetch"].as_bool().unwrap_or(false));
                let e = &step["expect"];
                assert_eq!(got.kind(), e["kind"].as_str().unwrap(), "{name}: {step} got {got:?}");
                match got {
                    RangePoll::RequestWindow(request) => {
                        let shape = (
                            u64::from(request.start_index),
                            u64::from(request.count),
                            request.renewal,
                        );
                        let want = (u(&e["start"]), u(&e["count"]), e["renewal"].as_bool().unwrap());
                        assert_eq!(shape, want, "{name}: {step}");
                        assert_eq!(
                            request.object_version_id.as_deref(),
                            Some(VERSION),
                            "{name}: the pin rides on every window"
                        );
                        last = Some(request);
                    }
                    RangePoll::Fetch { index, .. } | RangePoll::FetchViaApi { index, .. } => {
                        assert_eq!(u64::from(index), u(&e["index"]), "{name}: {step}");
                    }
                    _ => {}
                }
            }
            other => panic!("{name}: op {other}"),
        }
        steps += 1;
    }
    steps
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_direct_range_vector_row_runs_and_holds() {
        let got = run_all();
        assert_eq!(got, expected_report(), "a section that did not run is a failure");
        assert!(
            got.slots >= 10
                && got.window >= 7
                && got.demand_chunks >= 14
                && got.pieces >= 7
                && got.budget_steps >= 50
                && got.planner_steps >= 25,
            "the file shrank: {got:?}"
        );
    }
}
